function adapt(input, solve, kit) {
  let [n] = input;
  const limit = 2 ** 30 - 1;
  // LeetCode exposes the question as a global API; the hidden number lives inside it and changes on every call.
  globalThis.commonBits = num => {
    if (!Number.isInteger(num) || num < 0 || num > limit) throw new Error(`commonBits(${num}) needs a whole number from 0 to 2^30 - 1.`);
    let differ = n ^ num;
    let count = 30;
    while (differ > 0) {
      count -= differ & 1;
      differ >>= 1;
    }
    n ^= num;
    return count;
  };
  const result = solve();
  if (!Number.isInteger(result)) throw new Error('Return the hidden number as a whole number.');
  return result;
}

