function findNumber() {
  // Asking about 0 leaves the hidden number alone and reveals how many 0 bits it has.
  // Then each single-bit question moves that count up or down by one, which tells the bit, and flips it.
  let zeros = commonBits(0);
  let n = 0;
  for (let i = 0; i < 30; i++) {
    const count = commonBits(2 ** i);
    if (count > zeros) {
      n += 2 ** i;
      zeros += 1;
    } else {
      zeros -= 1;
    }
  }
  return n;
}

